SELECT P.ID AS permissionRefId, P.PERMISSION_CODE AS permissionCode, P.OWNER_TYPE AS ownerType FROM PEACH_PERMISSION_DEFINITION P WHERE P.ID IN
#{permissionRefId}
AND P.STATUS = 'ACTIVE' AND P.IS_DELETE = 0 AND P.DELEGABLE = 1 AND (P.APP_REF_ID IS NULL OR P.APP_REF_ID = #{appRefId}) AND ((P.OWNER_TYPE = 'SYSTEM' AND P.TENANT_REF_ID IS NULL) OR (P.OWNER_TYPE = 'TENANT' AND P.TENANT_REF_ID = #{tenantRefId}))

mapper.update:
UPDATE PEACH_ROLE_PERMISSION
SET STATUS = 'DISABLED', IS_DELETE = 1,
    DELETED_AT = CURRENT_TIMESTAMP(3), VERSION = VERSION + 1
WHERE TENANT_REF_ID = #{tenantRefId} AND ROLE_REF_ID = #{roleRefId}
  AND PERMISSION_REF_ID = #{permissionRefId}
  AND STATUS = 'ACTIVE' AND IS_DELETE = 0
